mod adapter_timing {
    use std::{string::String, vec::Vec};
    static RECORDS: std::sync::Mutex<Vec<String>> = std::sync::Mutex::new(Vec::new());
    pub(super) struct Scope(&'static str, Option<std::time::Instant>);
    pub(super) fn enabled() -> bool { std::env::var_os("TERMINAL_STARTUP_DIAGNOSTICS").is_some_and(|v| v == "1") }
    pub(super) fn record(s: String) { RECORDS.lock().unwrap().push(s); }
    pub(super) fn flush() { for s in RECORDS.lock().unwrap().drain(..) { std::eprintln!("{}",s); } }
    impl Scope { pub(super) fn new(name: &'static str) -> Self { Self(name, enabled().then(std::time::Instant::now)) } }
    impl Drop for Scope { fn drop(&mut self) { if let Some(start) = self.1 { record(std::format!("terminal-wgpu-adapter cost={} duration_us={}", self.0, start.elapsed().as_micros()));  } } }
}

